def course_order(n: int, prereqs: list[list[int]]) -> list[int]:
    adj, indeg = [[] for _ in range(n)], [0] * n
    for course, needs in prereqs:
        adj[needs].append(course)
        indeg[course] += 1
    placed, order = [False] * n, []
    for _ in range(n):
        ready = [i for i in range(n) if not placed[i] and indeg[i] == 0]
        if not ready:
            return []
        u = min(ready)
        placed[u] = True
        order.append(u)
        for v in adj[u]:
            indeg[v] -= 1
    return order
